// @ts-check

import { getDependency, getRequire, isNodejsRuntime } from '../../utils/Runtime.js'
import { ReceiverNative } from '../receiver/ReceiverNative.js' // needed for global.ReceiverNative

/** @type {any | null} */
let library = null
/** @type {any | null} */
let path = null
/** Guards against re-entrant/concurrent initialization of the native library. */
let isLoading = false

/** @type {ReturnType<import('module').createRequire>} */
const requireDynamic = getRequire(import.meta.url)

class TransmitterWrapper {
    static isNativeLibraryLoaded() {
        return Boolean(library)
    }

    static loadNativeLibrary() {
        if (!isNodejsRuntime()) {
            throw new Error('loadNativeLibrary is not supported in this runtime')
        }
        if (this.isNativeLibraryLoaded()) {
            return
        }
        if (isLoading) {
            throw new Error('Native library is already being loaded')
        }
        isLoading = true
        try {
            if (!path) {
                path = requireDynamic('path')
            }
            const packagePath = getDependency('hypertube-binaries', import.meta.url)

            const binariesRootPath = path.dirname(packagePath)
            const loadedLibrary = requireDynamic(packagePath)
            loadedLibrary.initializeTransmitter(binariesRootPath)
            // @ts-expect-error ReceiverNative is attached at runtime
            loadedLibrary.setReceiverNative(global?.ReceiverNative)
            library = loadedLibrary
        } finally {
            isLoading = false
        }
    }

    /**
     * @param {string} licenseKey
     */
    static activate(licenseKey) {
        this.loadNativeLibrary()
        return library.activate(licenseKey)
    }

    /**
     * @param {Uint8Array} messageArray
     * @param {string} configSource
     * @returns {Uint8Array}
     */
    static sendCommand(messageArray, configSource) {
        this.loadNativeLibrary()
        return library.sendCommand(messageArray, configSource)
    }

    /**
     * @param {string} configSource
     */
    static setConfigSource(configSource) {
        this.loadNativeLibrary()
        return library.setConfigSource(configSource)
    }

    /**
     * @param {string} path
     */
    static setWorkingDirectory(path) {
        this.loadNativeLibrary()
        library.setWorkingDirectory(path)
    }
}

export { TransmitterWrapper }
